import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function makeBucket(p) {
  return {
    fresh() { return { num: p.capacity * p.per, last: null } },
    advance(s, t) {
      if (s.last === null) { s.last = t; return }
      s.num += p.refill * (t - s.last)
      const max = p.capacity * p.per
      if (s.num > max) s.num = max
      s.last = t
    },
    ask(s) { return s.num >= p.per },
    record(s) { s.num -= p.per },
  }
}

function makeWindow(p) {
  return {
    fresh() { return { ticks: [] } },
    advance(s, t) {
      const cut = t - p.span
      s.ticks = s.ticks.filter((x) => x > cut)
    },
    ask(s) { return BigInt(s.ticks.length) < p.limit },
    record(s, t) { s.ticks.push(t) },
  }
}

function run(mode, text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  let started = false
  let lastTick = null
  let allowed = 0
  let denied = 0

  const int = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) {
      throw new Fail(`${field} must be an integer of at least ${least}`)
    }
    return BigInt(v)
  }

  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const w = f[0]
    const fail = (m) => { throw new Fail(`line ${i + 1}: ${m}`) }
    try {
      if (w === 'bucket' || w === 'window' || w === 'route') {
        if (started) fail('declarations must come before the first event')
      }
      if (w === 'bucket') {
        if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const capacity = int(f[2], 'capacity', 1)
        const refill = int(f[3], 'refill', 0)
        const per = int(f[4], 'per', 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], impl: makeBucket({ capacity, refill, per }), states: new Map() })
      } else if (w === 'window') {
        if (f.length !== 4) fail('expected window <name> <limit> <span>')
        if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
        const limit = int(f[2], 'limit', 0)
        const span = int(f[3], 'span', 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], impl: makeWindow({ limit, span }), states: new Map() })
      } else if (w === 'route') {
        if (f.length < 3) fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
        const list = []
        for (const n of f.slice(2)) {
          if (!policies.has(n)) fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(f[1], list)
      } else if (w === 'event') {
        if (f.length !== 3) fail('expected event <tick> <key>')
        let tick
        try { tick = int(f[1], 'tick', 0) } catch (e) { fail(e.message) }
        if (!NAME.test(f[2])) fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        started = true
        lastTick = tick
        const key = f[2]
        let best = null
        for (const [pre, list] of routes) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let refused = null
        if (best !== null) {
          const list = routes.get(best)
          const sts = list.map((p) => {
            let s = p.states.get(key)
            if (!s) { s = p.impl.fresh(); p.states.set(key, s) }
            p.impl.advance(s, tick)
            return s
          })
          for (let j = 0; j < list.length; j++) {
            if (!list[j].impl.ask(sts[j])) { refused = list[j].name; break }
          }
          if (refused === null) list.forEach((p, j) => p.impl.record(sts[j], tick))
        }
        let st = stats.get(key)
        if (!st) { st = { a: 0, d: 0 }; stats.set(key, st) }
        if (refused === null) { st.a++; allowed++; out.push(`${tick} ${key} allow`) }
        else { st.d++; denied++; out.push(`${tick} ${key} deny ${refused}`) }
      } else {
        fail(`unknown directive ${w}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw e
      throw new Fail(`line ${i + 1}: ${e.message}`)
    }
  })

  if (mode === 'replay') return out
  const res = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  res.push(`total allowed=${allowed} denied=${denied}`)
  return res
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
try {
  const lines = run(args[0], input)
  process.stdout.write(lines.map((l) => l + '\n').join(''))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
